const casRnd=()=>{try{const a=new Uint32Array(1);crypto.getRandomValues(a);return a[0]/4294967296}catch(e){return Math.random()}};
const CAS_CAP=20000,CAS_LOSS=1500,BETS=[10,25,50,100,250,500],CAS={tab:'slots',bet:50,busy:false,bj:null,rou:{kind:'red',num:7}};
function casEnsure(){M.cas=M.cas||{};const c=M.cas;if(c.chips==null){Object.assign(c,{chips:200,net:0,wag:0,spins:0,hands:0,wins:0,best:0,peak:200,maxbet:0,j7:0,bjn:0,rnum:0,bought:0,wheels:0,day:{d:0,loss:0,wheel:0}})}return c}
function casDay(){const c=casEnsure(),d=dayN();if(!c.day||c.day.d!==d)c.day={d,loss:0,wheel:0};return c.day}
const casOpenToday=()=>casDay().loss<CAS_LOSS;
function casOnSP(n){const c=casEnsure(),g=Math.round(n*3);if(g<=0)return;c.chips=Math.min(CAS_CAP,c.chips+g);c.peak=Math.max(c.peak||0,c.chips);mDirty=true;casBalUp();mxFloat('+'+g+' chips','#f2c14e')}
const casBetAmt=()=>CAS.allin?Math.max(0,casEnsure().chips):CAS.bet;
function casCanBet(bet){const c=casEnsure();if(CAS.busy)return false;if(!(BETS.includes(bet)||(CAS.allin&&bet===c.chips&&bet>=BETS[0])))return false;if(!casOpenToday()){toast('The casino is closed for today. Go study!');return false}if(c.chips<bet){toast('Not enough chips. Study to earn more!');return false}return true}
function casBetTake(bet){const c=casEnsure();c.chips-=bet;c.wag+=bet;c.maxbet=Math.max(c.maxbet||0,bet);mDirty=true}
function casSettle(bet,pay){const c=casEnsure(),day=casDay();c.chips=Math.min(CAS_CAP,c.chips+pay);c.net+=pay-bet;day.loss=Math.max(0,day.loss+bet-pay);c.best=Math.max(c.best||0,pay);if(pay>bet)c.wins++;c.peak=Math.max(c.peak||0,c.chips);mDirty=true;try{checkAch()}catch(e){}}
let casShown=null;
function casBalUp(){const c=casEnsure(),to=c.chips,t=to.toLocaleString();document.querySelectorAll('#casov .cas-betamt').forEach(e=>e.textContent=casBetAmt().toLocaleString());const w=document.getElementById('casChips');if(w)w.textContent=t;const e=document.getElementById('casBal');if(!e)return;
 const from=casShown==null?to:casShown;casShown=to;if(RM||!jxOn()||Math.abs(to-from)<5){e.textContent=t;return}
 const t0=performance.now(),up=to>from;e.classList.toggle('cas-up',up);e.classList.toggle('cas-dn',!up);(function st(n){const k=Math.min(1,(n-t0)/650),v=Math.round(from+(to-from)*(1-Math.pow(1-k,3)));e.textContent=v.toLocaleString();if(k<1&&document.body.contains(e))requestAnimationFrame(st);else{e.textContent=t;setTimeout(()=>{e.classList.remove('cas-up','cas-dn')},500)}})(t0)}
